import{i as e,r as t,s as n,t as r}from"./app-CuN03z5x.js";var i=JSON.parse(`{"path":"/guide/http-server/","title":"HTTP-сервер и JSON API","lang":"ru-RU","frontmatter":{"prev":"/guide/logging-and-debugging/best-practices.md","next":"/guide/http-server/tests.md"},"git":{"updatedTime":1792178217000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"b847b706a7e3604ef0f762bdfc07d76db1b7767b","time":1792178217000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"fix"}]},"filePathRelative":"guide/http-server/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="http-сервер-и-json-api" tabindex="-1"><a class="header-anchor" href="#http-сервер-и-json-api"><span>HTTP-сервер и JSON API</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Научиться создать первую HTTP-версию Task Manager API средствами стандартного пакета <code>net/http</code>: принять запрос, выбрать маршрут, проверить входной JSON, вызвать бизнес-логику, вернуть JSON-ответ и протестировать handler без запуска настоящего сервера.</p><p>В этой главе HTTP-слой намеренно строится без фреймворка. Так будет видно, из каких частей состоит API и что именно позже упростит Gin. Бизнес-логика задач не должна зависеть от конкретного способа доставки запроса: сегодня её вызывает HTTP handler, завтра — CLI или другой transport.</p><div class="hint-container tip"><p class="hint-container-title">Требуется Go 1.22 или новее</p><p>Новые шаблоны маршрутов <code>ServeMux</code>, например <code>GET /tasks/{id}</code>, и <code>r.PathValue(&quot;id&quot;)</code> появились в Go 1.22. Проверьте установленную версию:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go version</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div></div><h2 id="что-происходит-при-http-запросе" tabindex="-1"><a class="header-anchor" href="#что-происходит-при-http-запросе"><span>Что происходит при HTTP-запросе</span></a></h2><p>Клиент отправляет request, а сервер формирует response:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">клиент → HTTP request → ServeMux → handler → service → HTTP response → клиент</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Request содержит метод, путь, заголовки и иногда тело. Response содержит статус, заголовки и тело.</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"><span class="token request-line"><span class="token method property">POST</span> <span class="token request-target url">/tasks</span> <span class="token http-version property">HTTP/1.1</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span><span class="token property">&quot;title&quot;</span><span class="token operator">:</span><span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;priority&quot;</span><span class="token operator">:</span><span class="token number">2</span><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Успешный ответ на создание задачи:</p><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line"><span class="token response-status"><span class="token http-version property">HTTP/1.1</span> <span class="token status-code number">201</span> <span class="token reason-phrase string">Created</span></span></span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span><span class="token property">&quot;id&quot;</span><span class="token operator">:</span><span class="token number">1</span><span class="token punctuation">,</span><span class="token property">&quot;title&quot;</span><span class="token operator">:</span><span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span><span class="token property">&quot;priority&quot;</span><span class="token operator">:</span><span class="token number">2</span><span class="token punctuation">,</span><span class="token property">&quot;completed&quot;</span><span class="token operator">:</span><span class="token boolean">false</span><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="net-http-и-handler" tabindex="-1"><a class="header-anchor" href="#net-http-и-handler"><span><code>net/http</code> и handler</span></a></h2><p>HTTP handler — это код, который получает <code>http.ResponseWriter</code> и <code>*http.Request</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">health</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">Header</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Content-Type&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">WriteHeader</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusOK<span class="token punctuation">)</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">Write</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;status&quot;:&quot;ok&quot;}\`</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>r</code> содержит данные запроса: метод, URL, заголовки, body и <code>Context()</code>;</li><li><code>w</code> формирует ответ: заголовки, статус и body.</li></ul><p>Метод <code>w.Write</code> неявно отправляет статус <code>200 OK</code>, если статус ещё не был записан. Обычно API удобнее создавать через <code>json.Encoder</code>, но порядок остаётся важным: сначала заголовки, затем <code>WriteHeader</code>, затем body.</p><h2 id="запуск-минимального-сервера" tabindex="-1"><a class="header-anchor" href="#запуск-минимального-сервера"><span>Запуск минимального сервера</span></a></h2><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;log&quot;</span></span>
<span class="line">	<span class="token string">&quot;net/http&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">health</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">Header</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Content-Type&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">WriteHeader</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusOK<span class="token punctuation">)</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">Write</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;status&quot;:&quot;ok&quot;}\`</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	mux <span class="token operator">:=</span> http<span class="token punctuation">.</span><span class="token function">NewServeMux</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	mux<span class="token punctuation">.</span><span class="token function">HandleFunc</span><span class="token punctuation">(</span><span class="token string">&quot;GET /healthz&quot;</span><span class="token punctuation">,</span> health<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	log<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;сервер слушает http://localhost:8080&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> http<span class="token punctuation">.</span><span class="token function">ListenAndServe</span><span class="token punctuation">(</span><span class="token string">&quot;:8080&quot;</span><span class="token punctuation">,</span> mux<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		log<span class="token punctuation">.</span><span class="token function">Fatal</span><span class="token punctuation">(</span>err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Запустите сервер:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line">go run <span class="token builtin class-name">.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>В другом терминале выполните:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-i</span> http://localhost:8080/healthz</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>http.NewServeMux</code> сопоставляет запрос с маршрутом. Шаблон <code>GET /healthz</code> задаёт <strong>и метод, и путь</strong>. Если зарегистрирован только этот шаблон, <code>POST /healthz</code> не попадёт в handler.</p><p>Для учебного сервера подойдёт <code>http.ListenAndServe</code>. В главе о конфигурации и жизненном цикле заменим его на <code>http.Server</code>, добавим таймауты и graceful shutdown.</p><h2 id="маршруты-task-manager-api" tabindex="-1"><a class="header-anchor" href="#маршруты-task-manager-api"><span>Маршруты Task Manager API</span></a></h2><p>Сделаем небольшой контракт первой версии API:</p><table><thead><tr><th>Метод и путь</th><th>Назначение</th><th>Успешный статус</th></tr></thead><tbody><tr><td><code>GET /healthz</code></td><td>Проверить, что приложение отвечает</td><td><code>200 OK</code></td></tr><tr><td><code>GET /tasks</code></td><td>Получить список задач</td><td><code>200 OK</code></td></tr><tr><td><code>POST /tasks</code></td><td>Создать задачу</td><td><code>201 Created</code></td></tr><tr><td><code>POST /tasks/{id}/complete</code></td><td>Отметить задачу выполненной</td><td><code>200 OK</code></td></tr></tbody></table><p>Регистрация маршрутов остаётся в одном месте:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span> http<span class="token punctuation">.</span>Handler <span class="token punctuation">{</span></span>
<span class="line">	mux <span class="token operator">:=</span> http<span class="token punctuation">.</span><span class="token function">NewServeMux</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	mux<span class="token punctuation">.</span><span class="token function">HandleFunc</span><span class="token punctuation">(</span><span class="token string">&quot;GET /healthz&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>health<span class="token punctuation">)</span></span>
<span class="line">	mux<span class="token punctuation">.</span><span class="token function">HandleFunc</span><span class="token punctuation">(</span><span class="token string">&quot;GET /tasks&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>listTasks<span class="token punctuation">)</span></span>
<span class="line">	mux<span class="token punctuation">.</span><span class="token function">HandleFunc</span><span class="token punctuation">(</span><span class="token string">&quot;POST /tasks&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>createTask<span class="token punctuation">)</span></span>
<span class="line">	mux<span class="token punctuation">.</span><span class="token function">HandleFunc</span><span class="token punctuation">(</span><span class="token string">&quot;POST /tasks/{id}/complete&quot;</span><span class="token punctuation">,</span> api<span class="token punctuation">.</span>completeTask<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">return</span> mux</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>{id}</code> — path-параметр. Извлечь его можно через <code>r.PathValue</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">id<span class="token punctuation">,</span> err <span class="token operator">:=</span> strconv<span class="token punctuation">.</span><span class="token function">Atoi</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span><span class="token function">PathValue</span><span class="token punctuation">(</span><span class="token string">&quot;id&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">||</span> id <span class="token operator">&lt;</span> <span class="token number">1</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;идентификатор задачи должен быть положительным числом&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">return</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не доверяйте параметрам URL: строка <code>abc</code>, <code>0</code> и <code>-1</code> не должны попадать в сервис как корректный ID.</p><h2 id="слои-приложения" tabindex="-1"><a class="header-anchor" href="#слои-приложения"><span>Слои приложения</span></a></h2><p>HTTP handler отвечает только за HTTP: чтение запроса, валидацию формы данных, выбор статуса и кодирование ответа. Правила предметной области и работа с хранилищем остаются ниже:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">HTTP handler → service → repository / TaskStore</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Для связи handler с приложением опишем небольшой интерфейс. Он зависит от потребностей handler, а не от конкретной реализации Store:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> TaskService <span class="token keyword">interface</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token function">List</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token function">Create</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> input task<span class="token punctuation">.</span>CreateInput<span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token function">Complete</span><span class="token punctuation">(</span>ctx context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> id <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> API <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	service TaskService</span>
<span class="line">	logger  <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">New</span><span class="token punctuation">(</span>service TaskService<span class="token punctuation">,</span> logger <span class="token operator">*</span>slog<span class="token punctuation">.</span>Logger<span class="token punctuation">)</span> <span class="token operator">*</span>API <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">if</span> logger <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		logger <span class="token operator">=</span> slog<span class="token punctuation">.</span><span class="token function">Default</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> <span class="token operator">&amp;</span>API<span class="token punctuation">{</span>service<span class="token punctuation">:</span> service<span class="token punctuation">,</span> logger<span class="token punctuation">:</span> logger<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Здесь <code>task.CreateInput</code> — отдельный тип входных данных для бизнес-логики:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> CreateInput <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Title    <span class="token builtin">string</span></span>
<span class="line">	Priority <span class="token builtin">int</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Так HTTP-пакет не зависит от map, mutex или будущего PostgreSQL-репозитория. В тестах вместо настоящего сервиса можно передать маленький fake.</p><p>В текущей учебной реализации <code>TaskStore.Complete</code> уже возвращает <code>store.ErrTaskNotFound</code>. Когда сервис передаёт эту известную причину выше, HTTP-слой может преобразовать её в <code>404</code>. При появлении PostgreSQL service сохранит тот же внешний контракт и сам сопоставит ошибку репозитория с <code>store.ErrTaskNotFound</code> или отдельной доменной ошибкой.</p><h2 id="json-ответы" tabindex="-1"><a class="header-anchor" href="#json-ответы"><span>JSON-ответы</span></a></h2><p>Повторяющийся код JSON-ответа вынесем в helper:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">writeJSON</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> status <span class="token builtin">int</span><span class="token punctuation">,</span> value any<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">Header</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Set</span><span class="token punctuation">(</span><span class="token string">&quot;Content-Type&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;application/json; charset=utf-8&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	w<span class="token punctuation">.</span><span class="token function">WriteHeader</span><span class="token punctuation">(</span>status<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">NewEncoder</span><span class="token punctuation">(</span>w<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Encode</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token comment">// После WriteHeader нельзя безопасно изменить уже отправленный ответ.</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> errorResponse <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Error <span class="token builtin">string</span> <span class="token string">\`json:&quot;error&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">writeError</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> status <span class="token builtin">int</span><span class="token punctuation">,</span> message <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token function">writeJSON</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> status<span class="token punctuation">,</span> errorResponse<span class="token punctuation">{</span>Error<span class="token punctuation">:</span> message<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>json.Encoder.Encode</code> добавляет перевод строки в конец JSON — это нормально. <code>Content-Type</code> нужно установить <strong>до</strong> <code>WriteHeader</code>: после отправки заголовков изменить их уже нельзя.</p><p>Список задач возвращается очень коротко:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">listTasks</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	tasks<span class="token punctuation">,</span> err <span class="token operator">:=</span> api<span class="token punctuation">.</span>service<span class="token punctuation">.</span><span class="token function">List</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		api<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось получить задачи&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> <span class="token string">&quot;внутренняя ошибка сервера&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token function">writeJSON</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusOK<span class="token punctuation">,</span> tasks<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>r.Context()</code> связан с жизненным циклом запроса. Передавайте его дальше в service, репозиторий и внешние вызовы, чтобы отмена клиента или будущий серверный дедлайн могли остановить ненужную работу.</p><h2 id="чтение-и-проверка-json-запроса" tabindex="-1"><a class="header-anchor" href="#чтение-и-проверка-json-запроса"><span>Чтение и проверка JSON-запроса</span></a></h2><p>Для создания задачи определим HTTP-представление тела:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> createTaskRequest <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	Title    <span class="token builtin">string</span> <span class="token string">\`json:&quot;title&quot;\`</span></span>
<span class="line">	Priority <span class="token builtin">int</span>    <span class="token string">\`json:&quot;priority&quot;\`</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Это не обязательно та же структура, что <code>task.Task</code>. Клиент не должен передавать <code>id</code> и <code>completed</code>: ID выдаёт приложение, а выполнение меняется отдельной операцией.</p><p>Создадим helper, который ограничивает размер body, запрещает неизвестные поля и принимает ровно одно JSON-значение:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">decodeJSON</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">,</span> dst any<span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">	r<span class="token punctuation">.</span>Body <span class="token operator">=</span> http<span class="token punctuation">.</span><span class="token function">MaxBytesReader</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> r<span class="token punctuation">.</span>Body<span class="token punctuation">,</span> <span class="token number">1</span><span class="token operator">&lt;&lt;</span><span class="token number">20</span><span class="token punctuation">)</span> <span class="token comment">// не больше 1 MiB</span></span>
<span class="line"></span>
<span class="line">	decoder <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">NewDecoder</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span>Body<span class="token punctuation">)</span></span>
<span class="line">	decoder<span class="token punctuation">.</span><span class="token function">DisallowUnknownFields</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> decoder<span class="token punctuation">.</span><span class="token function">Decode</span><span class="token punctuation">(</span>dst<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;некорректный JSON-запрос&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> decoder<span class="token punctuation">.</span><span class="token function">Decode</span><span class="token punctuation">(</span><span class="token operator">&amp;</span><span class="token keyword">struct</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> io<span class="token punctuation">.</span>EOF <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;в body должен быть один JSON-объект&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>DisallowUnknownFields</code> защитит от опечатки клиента: поле <code>priorty</code> не будет молча проигнорировано. Проверка второго <code>Decode</code> не позволит передать два JSON-объекта подряд. Ограничение размера body — базовая защита от слишком больших запросов.</p><h2 id="валидация-и-создание-задачи" tabindex="-1"><a class="header-anchor" href="#валидация-и-создание-задачи"><span>Валидация и создание задачи</span></a></h2><p>Handler проверяет, что запрос имеет корректную форму, а сервис обязан сохранять бизнес-инварианты и для других входов, не только HTTP.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">createTask</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> request createTaskRequest</span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span><span class="token function">decodeJSON</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> r<span class="token punctuation">,</span> <span class="token operator">&amp;</span>request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	request<span class="token punctuation">.</span>Title <span class="token operator">=</span> strings<span class="token punctuation">.</span><span class="token function">TrimSpace</span><span class="token punctuation">(</span>request<span class="token punctuation">.</span>Title<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> request<span class="token punctuation">.</span>Title <span class="token operator">==</span> <span class="token string">&quot;&quot;</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;название задачи обязательно&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> request<span class="token punctuation">.</span>Priority <span class="token operator">&lt;</span> <span class="token number">1</span> <span class="token operator">||</span> request<span class="token punctuation">.</span>Priority <span class="token operator">&gt;</span> <span class="token number">5</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;приоритет должен быть от 1 до 5&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	createdTask<span class="token punctuation">,</span> err <span class="token operator">:=</span> api<span class="token punctuation">.</span>service<span class="token punctuation">.</span><span class="token function">Create</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> task<span class="token punctuation">.</span>CreateInput<span class="token punctuation">{</span></span>
<span class="line">		Title<span class="token punctuation">:</span>    request<span class="token punctuation">.</span>Title<span class="token punctuation">,</span></span>
<span class="line">		Priority<span class="token punctuation">:</span> request<span class="token punctuation">.</span>Priority<span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		api<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось создать задачу&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> <span class="token string">&quot;внутренняя ошибка сервера&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	api<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">&quot;задача создана&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;task_id&quot;</span><span class="token punctuation">,</span> createdTask<span class="token punctuation">.</span>ID<span class="token punctuation">)</span></span>
<span class="line">	<span class="token function">writeJSON</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusCreated<span class="token punctuation">,</span> createdTask<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для недопустимых входных данных возвращаем <code>400 Bad Request</code>, а не <code>500</code>: ошибка на стороне клиента. При успешном создании используем <code>201 Created</code>.</p><h2 id="изменение-существующеи-задачи-и-404" tabindex="-1"><a class="header-anchor" href="#изменение-существующеи-задачи-и-404"><span>Изменение существующей задачи и <code>404</code></span></a></h2><p>Превратим известную ошибку сервиса «задача не найдена» в HTTP-статус <code>404 Not Found</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">completeTask</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	id<span class="token punctuation">,</span> err <span class="token operator">:=</span> strconv<span class="token punctuation">.</span><span class="token function">Atoi</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span><span class="token function">PathValue</span><span class="token punctuation">(</span><span class="token string">&quot;id&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">||</span> id <span class="token operator">&lt;</span> <span class="token number">1</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusBadRequest<span class="token punctuation">,</span> <span class="token string">&quot;идентификатор задачи должен быть положительным числом&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	completedTask<span class="token punctuation">,</span> err <span class="token operator">:=</span> api<span class="token punctuation">.</span>service<span class="token punctuation">.</span><span class="token function">Complete</span><span class="token punctuation">(</span>r<span class="token punctuation">.</span><span class="token function">Context</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> id<span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">if</span> errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> store<span class="token punctuation">.</span>ErrTaskNotFound<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusNotFound<span class="token punctuation">,</span> <span class="token string">&quot;задача не найдена&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		api<span class="token punctuation">.</span>logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось завершить задачу&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;task_id&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">		<span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> <span class="token string">&quot;внутренняя ошибка сервера&quot;</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token keyword">return</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token function">writeJSON</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusOK<span class="token punctuation">,</span> completedTask<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Сравнивайте причины через <code>errors.Is</code>, а не текст ошибки. Наружу не отдавайте технические детали: они полезны в структурированном логе, но не клиенту API.</p><h2 id="сборка-сервера" tabindex="-1"><a class="header-anchor" href="#сборка-сервера"><span>Сборка сервера</span></a></h2><p><code>main</code> соединяет зависимости приложения:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">logger <span class="token operator">:=</span> slog<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>slog<span class="token punctuation">.</span><span class="token function">NewTextHandler</span><span class="token punctuation">(</span>os<span class="token punctuation">.</span>Stderr<span class="token punctuation">,</span> <span class="token boolean">nil</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">store <span class="token operator">:=</span> store<span class="token punctuation">.</span><span class="token function">NewTaskStore</span><span class="token punctuation">(</span>logger<span class="token punctuation">)</span></span>
<span class="line">service <span class="token operator">:=</span> taskservice<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>store<span class="token punctuation">)</span></span>
<span class="line">api <span class="token operator">:=</span> httpapi<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span>service<span class="token punctuation">,</span> logger<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">server <span class="token operator">:=</span> <span class="token operator">&amp;</span>http<span class="token punctuation">.</span>Server<span class="token punctuation">{</span></span>
<span class="line">	Addr<span class="token punctuation">:</span>              <span class="token string">&quot;:8080&quot;</span><span class="token punctuation">,</span></span>
<span class="line">	Handler<span class="token punctuation">:</span>           api<span class="token punctuation">.</span><span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">	ReadHeaderTimeout<span class="token punctuation">:</span> <span class="token number">5</span> <span class="token operator">*</span> time<span class="token punctuation">.</span>Second<span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">logger<span class="token punctuation">.</span><span class="token function">Info</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP-сервер запущен&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;address&quot;</span><span class="token punctuation">,</span> server<span class="token punctuation">.</span>Addr<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">if</span> err <span class="token operator">:=</span> server<span class="token punctuation">.</span><span class="token function">ListenAndServe</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token operator">&amp;&amp;</span> <span class="token operator">!</span>errors<span class="token punctuation">.</span><span class="token function">Is</span><span class="token punctuation">(</span>err<span class="token punctuation">,</span> http<span class="token punctuation">.</span>ErrServerClosed<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	logger<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token string">&quot;HTTP-сервер завершился с ошибкой&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;err&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>http.Server</code> даёт место для настройки таймаутов. Сейчас сервер завершается обычным способом; корректную остановку через <code>signal.NotifyContext</code> и <code>server.Shutdown</code> добавим в главе о жизненном цикле.</p><h2 id="проверка-api-через-curl" tabindex="-1"><a class="header-anchor" href="#проверка-api-через-curl"><span>Проверка API через <code>curl</code></span></a></h2><p>После запуска сервера выполните:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-i</span> http://localhost:8080/healthz</span>
<span class="line"></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-i</span> http://localhost:8080/tasks</span>
<span class="line"></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-i</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/tasks <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-H</span> <span class="token string">&#39;Content-Type: application/json&#39;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-d</span> <span class="token string">&#39;{&quot;title&quot;:&quot;Купить молоко&quot;,&quot;priority&quot;:2}&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="token function">curl</span> <span class="token parameter variable">-i</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/tasks/1/complete</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Проверьте также ошибочные случаи: пустое название, приоритет <code>0</code>, некорректный JSON и несуществующий ID. API должен вернуть понятный JSON с корректным статусом, а не panic и не HTML-страницу.</p><h2 id="тестирование-handler-без-настоящего-сервера" tabindex="-1"><a class="header-anchor" href="#тестирование-handler-без-настоящего-сервера"><span>Тестирование handler без настоящего сервера</span></a></h2><p><code>httptest.NewRequest</code> создаёт тестовый request, а <code>httptest.NewRecorder</code> запоминает response. Сеть и порт не нужны:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token function">TestCreateTask</span><span class="token punctuation">(</span>t <span class="token operator">*</span>testing<span class="token punctuation">.</span>T<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	service <span class="token operator">:=</span> <span class="token operator">&amp;</span>fakeTaskService<span class="token punctuation">{</span></span>
<span class="line">		createdTask<span class="token punctuation">:</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span> Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	api <span class="token operator">:=</span> <span class="token function">New</span><span class="token punctuation">(</span>service<span class="token punctuation">,</span> <span class="token function">newTestLogger</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	request <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewRequest</span><span class="token punctuation">(</span></span>
<span class="line">		http<span class="token punctuation">.</span>MethodPost<span class="token punctuation">,</span></span>
<span class="line">		<span class="token string">&quot;/tasks&quot;</span><span class="token punctuation">,</span></span>
<span class="line">		strings<span class="token punctuation">.</span><span class="token function">NewReader</span><span class="token punctuation">(</span><span class="token string">\`{&quot;title&quot;:&quot;Купить молоко&quot;,&quot;priority&quot;:2}\`</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">)</span></span>
<span class="line">	recorder <span class="token operator">:=</span> httptest<span class="token punctuation">.</span><span class="token function">NewRecorder</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	api<span class="token punctuation">.</span><span class="token function">Router</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">ServeHTTP</span><span class="token punctuation">(</span>recorder<span class="token punctuation">,</span> request<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> recorder<span class="token punctuation">.</span>Code <span class="token operator">!=</span> http<span class="token punctuation">.</span>StatusCreated <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;status = %d, ожидался %d&quot;</span><span class="token punctuation">,</span> recorder<span class="token punctuation">.</span>Code<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusCreated<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> got task<span class="token punctuation">.</span>Task</span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">NewDecoder</span><span class="token punctuation">(</span>recorder<span class="token punctuation">.</span>Body<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">Decode</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>got<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;не удалось прочитать JSON-ответ: %v&quot;</span><span class="token punctuation">,</span> err<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> got <span class="token operator">!=</span> service<span class="token punctuation">.</span>createdTask <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;ответ = %+v, ожидалось %+v&quot;</span><span class="token punctuation">,</span> got<span class="token punctuation">,</span> service<span class="token punctuation">.</span>createdTask<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line">	<span class="token keyword">if</span> service<span class="token punctuation">.</span>createInput<span class="token punctuation">.</span>Title <span class="token operator">!=</span> <span class="token string">&quot;Купить молоко&quot;</span> <span class="token operator">||</span> service<span class="token punctuation">.</span>createInput<span class="token punctuation">.</span>Priority <span class="token operator">!=</span> <span class="token number">2</span> <span class="token punctuation">{</span></span>
<span class="line">		t<span class="token punctuation">.</span><span class="token function">Fatalf</span><span class="token punctuation">(</span><span class="token string">&quot;service получил %+v&quot;</span><span class="token punctuation">,</span> service<span class="token punctuation">.</span>createInput<span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Минимальный fake реализует интерфейс и сохраняет входные данные. Он не должен повторять логику настоящего сервиса:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">type</span> fakeTaskService <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	createdTask task<span class="token punctuation">.</span>Task</span>
<span class="line">	createInput task<span class="token punctuation">.</span>CreateInput</span>
<span class="line">	createErr   <span class="token builtin">error</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>service <span class="token operator">*</span>fakeTaskService<span class="token punctuation">)</span> <span class="token function">Create</span><span class="token punctuation">(</span><span class="token boolean">_</span> context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> input task<span class="token punctuation">.</span>CreateInput<span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	service<span class="token punctuation">.</span>createInput <span class="token operator">=</span> input</span>
<span class="line">	<span class="token keyword">return</span> service<span class="token punctuation">.</span>createdTask<span class="token punctuation">,</span> service<span class="token punctuation">.</span>createErr</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>service <span class="token operator">*</span>fakeTaskService<span class="token punctuation">)</span> <span class="token function">List</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span>Context<span class="token punctuation">)</span> <span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>service <span class="token operator">*</span>fakeTaskService<span class="token punctuation">)</span> <span class="token function">Complete</span><span class="token punctuation">(</span>context<span class="token punctuation">.</span>Context<span class="token punctuation">,</span> <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">error</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Тест handler проверяет HTTP-контракт: статус, JSON и то, какие данные переданы в service. Проверка реальной бизнес-логики остаётся в её unit-тестах.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="записывать-body-до-статуса" tabindex="-1"><a class="header-anchor" href="#записывать-body-до-статуса"><span>Записывать body до статуса</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line">w<span class="token punctuation">.</span><span class="token function">Write</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token function">byte</span><span class="token punctuation">(</span><span class="token string">\`{&quot;error&quot;:&quot;не найдено&quot;}\`</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">w<span class="token punctuation">.</span><span class="token function">WriteHeader</span><span class="token punctuation">(</span>http<span class="token punctuation">.</span>StatusNotFound<span class="token punctuation">)</span> <span class="token comment">// Уже поздно: клиент получил 200.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Устанавливайте заголовки и статус до записи body.</p><h3 id="смешивать-http-и-бизнес-логику" tabindex="-1"><a class="header-anchor" href="#смешивать-http-и-бизнес-логику"><span>Смешивать HTTP и бизнес-логику</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>api <span class="token operator">*</span>API<span class="token punctuation">)</span> <span class="token function">createTask</span><span class="token punctuation">(</span>w http<span class="token punctuation">.</span>ResponseWriter<span class="token punctuation">,</span> r <span class="token operator">*</span>http<span class="token punctuation">.</span>Request<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token comment">// Не храните задачи и не управляйте mutex прямо здесь.</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Handler переводит HTTP в вызов service. Это позволит заменить <code>net/http</code> на Gin в следующей главе без переписывания логики задач.</p><h3 id="игнорировать-ошибку-json-декодирования" tabindex="-1"><a class="header-anchor" href="#игнорировать-ошибку-json-декодирования"><span>Игнорировать ошибку JSON-декодирования</span></a></h3><p>Не продолжайте работу с нулевыми значениями структуры, если JSON не прочитан. Верните <code>400</code> и завершите handler.</p><h3 id="возвращать-клиенту-техническую-ошибку" tabindex="-1"><a class="header-anchor" href="#возвращать-клиенту-техническую-ошибку"><span>Возвращать клиенту техническую ошибку</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code class="language-go"><span class="line"><span class="token function">writeError</span><span class="token punctuation">(</span>w<span class="token punctuation">,</span> http<span class="token punctuation">.</span>StatusInternalServerError<span class="token punctuation">,</span> err<span class="token punctuation">.</span><span class="token function">Error</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Сообщение может раскрыть пути файлов, детали базы данных или внутренние правила. Логируйте исходную ошибку, а клиенту отдавайте стабильное безопасное сообщение.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>У вас есть первая рабочая HTTP-версия Task Manager API на стандартном <code>net/http</code>. В следующей главе реализуем тот же HTTP-слой на Gin, сравним объём кода и сохраним service и repository без изменений.</p>`,92)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};